#include <stdio.h>
#include <string.h>

#define N 510
#define INF 0x3f3f3f3f

int g[N][N];
int dist[N];
int st[N];

int main()
{
    int n,m;
    scanf("%d%d",&n,&m);

    memset(g,0x3f,sizeof g);

    while(m--)
    {
        int a,b,w;
        scanf("%d%d%d",&a,&b,&w);

        if(w<g[a][b])
        {
            g[a][b]=g[b][a]=w;
        }
    }

    memset(dist,0x3f,sizeof dist);

    int ans=0;

    for(int i=0;i<n;i++)
    {
        int t=-1;

        for(int j=1;j<=n;j++)
            if(!st[j]&&(t==-1||dist[j]<dist[t]))
                t=j;

        if(i&&dist[t]==INF)
        {
            puts("impossible");
            return 0;
        }

        if(i) ans+=dist[t];

        st[t]=1;

        for(int j=1;j<=n;j++)
            if(dist[j]>g[t][j])
                dist[j]=g[t][j];
    }

    printf("%d",ans);

    return 0;
}
